    "leftSidebar": { "type": "Card", "props": { "title": "Scene Hierarchy", "padding": "16px" }, "children": ["hierarchyList"] },
    "hierarchyList": { "type": "List", "children": ["sceneRoot", "mainCamera", "directionalLight", "environment", "groundPlane", "skyDome", "characters", "playerModel", "npcGuard", "npcMerchant", "props", "treasureChest", "barrel", "crate"] },
    
    "sceneRoot": { "type": "ListItem", "props": { "label": "Scene Root" }, "children": ["sceneRootToggle"] },
